"""Implementation exercises; each chapter has distinct difficulty levels."""
EXERCISES = {
 'Arrays & Strings': [('Return the largest value in an integer array; return null for an empty array.', 'Scan once; track maximum; handle negative values; O(n) time'), ('Return the length of the longest substring without repeated characters.', 'Sliding window; last seen positions; empty string; O(n) time'), ('Return the smallest substring containing every character of a target, including duplicates. Return an empty string if absent.', 'Frequency counts; expand and shrink window; track multiplicities; O(n+m) time')],
 'Linked Lists': [('Reverse a singly linked list and return its new head.', 'Previous/current/next pointers; null head; O(n) time and O(1) space'), ('Return the node where a linked-list cycle begins, or null if there is no cycle.', 'Floyd cycle detection; reset one pointer to head; find entry; constant extra space'), ('Merge k sorted linked lists into one sorted list.', 'Min heap or divide and conquer; handle empty lists; O(N log k) time')],
 'Stacks & Queues': [('Return whether a string of round, square and curly brackets is balanced.', 'Stack; matching pairs; reject unmatched closing brackets; empty string valid'), ('Implement a queue with two stacks, including enqueue, dequeue and empty.', 'Input and output stacks; transfer only when output empty; amortized O(1)'), ('Return the largest rectangle area in a histogram of nonnegative heights.', 'Monotonic stack; compute width on pop; flush remaining bars; O(n) time')],
 'Trees': [('Return the maximum depth of a binary tree; an empty tree has depth zero.', 'Recursive maximum of child depths plus one; null base case; O(n)'), ('Validate a binary search tree with unique keys.', 'Propagate strict lower and upper bounds; validate all descendants; O(n)'), ('Serialize and deserialize a binary tree while preserving its exact shape.', 'Traversal with null markers; consistent token parsing; round trip empty tree; O(n)')],
 'Graphs': [('Count connected components in an undirected graph given n vertices and an edge list.', 'Adjacency list; visited set; DFS or BFS from each unvisited vertex; isolated vertices'), ('Return shortest path distances from a source in an unweighted graph; use -1 for unreachable vertices.', 'BFS queue; initialize source distance zero; mark visited on enqueue; O(V+E)'), ('Return shortest distances from a source in a graph with nonnegative weighted edges.', 'Dijkstra min heap; relax edges; skip stale entries; unreachable vertices')],
 'Recursion & Backtracking': [('Generate all subsets of a list of distinct integers.', 'Include/exclude recursion; copy current subset; include empty subset'), ('Generate every permutation of a list that may contain duplicates, without duplicate results.', 'Sort input; used flags; skip equivalent choices; backtrack'), ('Return all valid arrangements of n queens on an n by n chessboard.', 'Place one queen per row; track columns and diagonals; undo choices')],
 'Sorting & Searching': [('Return the index of a target in a sorted array using binary search, or -1.', 'Inclusive bounds; safe midpoint; shrink interval; O(log n)'), ('Return the first and last index of a target in a sorted array, or [-1,-1].', 'Two boundary binary searches; duplicates; O(log n)'), ('Return the median of two sorted arrays in O(log(min(m,n))) time. At least one array is nonempty.', 'Partition shorter array; valid cross boundaries; odd and even totals; empty array')],
 'Dynamic Programming': [('Count ways to climb n stairs taking one or two steps; there is one way to climb zero stairs.', 'Base cases; Fibonacci recurrence; rolling state'), ('Return the minimum number of coins to make a target amount using unlimited positive denominations, or -1.', 'DP over amounts; unreachable sentinel; dp[0]=0; minimum transition'), ('Return the minimum edit distance between two strings using insert, delete and replace operations.', 'Prefix DP; empty prefix base cases; match or minimum of three operations')],
 'Hashing': [('Return the first nonrepeating character in a string, or null.', 'Frequency map; second scan in original order; O(n)'), ('Group strings into groups of anagrams.', 'Sorted or frequency signature; map signature to list; empty strings'), ('Implement an LRU cache with get and put in O(1) time, including capacity-zero behavior.', 'Hash map; doubly linked list; move to front; evict tail; update existing keys')],
 'Greedy Algorithms': [('Select the maximum number of nonoverlapping intervals, allowing touching endpoints.', 'Sort by end time; choose compatible next interval; empty input'), ('Return the minimum jumps needed to reach the final index of an array of maximum jump lengths, or -1.', 'Track current frontier and farthest reach; detect stalled frontier; linear time'), ('Return the minimum number of refueling stops to reach a target given initial fuel and sorted stations with fuel amounts, or -1.', 'Max heap of reachable stations; refuel with largest available; detect unreachable target')],
 'Programming': [('Implement a word-frequency counter ignoring letter case and punctuation.', 'Normalize case; tokenize words; dictionary counts'), ('Implement an iterator that flattens nested lists of integers lazily.', 'Explicit stack; expand nested lists; handle empty lists; lazy iteration'), ('Implement a bounded thread-safe queue with blocking put and get operations.', 'Lock; condition variables; wait in loops; notify after state change')],
 'System design': [('Implement an in-memory key-value store supporting put, get and delete.', 'Dictionary storage; overwrite existing keys; missing-key behavior'), ('Implement an expiring key-value cache using an injected clock and per-key TTL.', 'Store expiry timestamps; expire on access; overwrite TTL; deterministic clock'), ('Implement a per-client token-bucket rate limiter using an injected monotonic clock.', 'Refill based on elapsed time; cap at capacity; consume tokens atomically; isolate clients')],
}

def coding_rows():
    from .code_cases import execution_metadata
    for index, (chapter, levels) in enumerate(EXERCISES.items()):
        for level, (prompt, points) in zip(('easy','medium','hard'), levels):
            yield {**execution_metadata(f'coding-v1-{index:02}-{level}'), 'id':f'coding-v1-{index:02}-{level}', 'category':'technical',
                   'subcategory':chapter if chapter in ('Programming','System design') else 'DSA',
                   'chapter':chapter, 'difficulty':level, 'question_type':'code',
                   'question':'Write code: '+prompt+' Include a brief complexity explanation and edge-case examples.',
                   'expected_points':points.split('; '), 'key':None, 'options':[], 'options_json':[],
                   'correct_option_ids':[], 'option_explanations_json':{}, 'accepts_pseudocode':False,
                   'shuffle_options':False, 'negative_marking':False, 'snippet_text':'', 'snippet_language':'',
                   'time_limit_seconds':{'easy':600,'medium':900,'hard':1200}[level]}
